do $$begin create type public.finance_cost_class as enum('direct_cost','operating_expense','tax','other');exception when duplicate_object then null;end$$;
alter table public.finance_expenses add column if not exists cost_class public.finance_cost_class not null default 'operating_expense',add column if not exists invoice_id uuid references public.finance_invoices(id) on delete restrict;
create index if not exists finance_expenses_invoice_cost_idx on public.finance_expenses(invoice_id,cost_class,status,expense_on);
alter table public.finance_invoice_items add column if not exists estimated_unit_cost numeric(18,2),add column if not exists estimated_cost_total numeric(18,2);
alter table public.finance_invoice_items drop constraint if exists finance_invoice_items_estimated_unit_cost_nonnegative;alter table public.finance_invoice_items add constraint finance_invoice_items_estimated_unit_cost_nonnegative check(estimated_unit_cost is null or estimated_unit_cost>=0);
alter table public.finance_invoice_items drop constraint if exists finance_invoice_items_estimated_cost_total_nonnegative;alter table public.finance_invoice_items add constraint finance_invoice_items_estimated_cost_total_nonnegative check(estimated_cost_total is null or estimated_cost_total>=0);
create or replace function app.finance_invoice_margin_summary(p_invoice_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare v public.finance_invoices%rowtype;v_est numeric:=0;v_direct numeric:=0;v_opex numeric:=0;v_tax_exp numeric:=0;v_other numeric:=0;v_net_revenue numeric:=0;begin if not(app.has_permission('finance_invoices.create') or app.has_permission('finance_expenses.record') or app.has_permission('financial_reports.view')) then raise exception 'Missing finance permission.' using errcode='42501';end if;select * into v from public.finance_invoices where id=p_invoice_id;if not found then raise exception 'Invoice not found.' using errcode='P0002';end if;select coalesce(sum(coalesce(estimated_cost_total,coalesce(estimated_unit_cost,0)*quantity)),0) into v_est from public.finance_invoice_items where invoice_id=p_invoice_id;select coalesce(sum(total_amount) filter(where cost_class='direct_cost'),0),coalesce(sum(total_amount) filter(where cost_class='operating_expense'),0),coalesce(sum(total_amount) filter(where cost_class='tax'),0),coalesce(sum(total_amount) filter(where cost_class='other'),0) into v_direct,v_opex,v_tax_exp,v_other from public.finance_expenses where invoice_id=p_invoice_id and status='recorded';v_net_revenue:=greatest(0,v.paid_total-v.refunded_total);return jsonb_build_object('invoice_id',v.id,'currency',v.currency,'sales_value',v.grand_total,'invoice_tax',v.tax_total,'estimated_hpp',v_est,'estimated_margin',v.grand_total-v_est,'estimated_margin_percent',case when v.grand_total>0 then round(((v.grand_total-v_est)/v.grand_total)*100,2) else 0 end,'net_cash_revenue',v_net_revenue,'actual_direct_cost',v_direct,'allocated_opex',v_opex,'tax_expense',v_tax_exp,'other_cost',v_other,'actual_margin_before_opex_tax',v_net_revenue-v_direct,'actual_margin_after_linked_costs',v_net_revenue-v_direct-v_opex-v_tax_exp-v_other,'actual_margin_percent',case when v_net_revenue>0 then round(((v_net_revenue-v_direct-v_opex-v_tax_exp-v_other)/v_net_revenue)*100,2) else 0 end,'hpp_variance',v_direct-v_est);end$$;revoke all on function app.finance_invoice_margin_summary(uuid) from public,anon;grant execute on function app.finance_invoice_margin_summary(uuid) to authenticated;